-- Shared foods have separate stable IDs; private food IDs and owner constraints stay intact.
CREATE TABLE food_catalogue (
 catalogue_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 name varchar(300) NOT NULL CHECK(char_length(trim(name)) > 0),
 preparation varchar(40) NOT NULL DEFAULT 'as described',
 kcal_100g numeric(10,6) CHECK(kcal_100g BETWEEN 0 AND 1000),
 protein_100g numeric(9,6) CHECK(protein_100g BETWEEN 0 AND 100),
 carbs_100g numeric(9,6) CHECK(carbs_100g BETWEEN 0 AND 100),
 fat_100g numeric(9,6) CHECK(fat_100g BETWEEN 0 AND 100),
 source text NOT NULL,
 source_id text NOT NULL,
 dataset_version text NOT NULL,
 source_url text NOT NULL,
 provenance jsonb NOT NULL DEFAULT '{}',
 is_active boolean NOT NULL DEFAULT true,
 -- Nutrition provenance never establishes ingredient/allergen verification.
 allergens text[] NOT NULL DEFAULT '{}',
 allergen_complete boolean NOT NULL DEFAULT false,
 ingredient_labels text[] NOT NULL DEFAULT '{}',
 UNIQUE(source,source_id)
);
ALTER TABLE nutrition_food
 ADD COLUMN provenance jsonb NOT NULL DEFAULT '{}',
 ADD COLUMN allergens text[] NOT NULL DEFAULT '{}',
 ADD COLUMN allergen_complete boolean NOT NULL DEFAULT false,
 ADD COLUMN ingredient_labels text[] NOT NULL DEFAULT '{}',
 ALTER COLUMN kcal_100g TYPE numeric(10,6),
 ALTER COLUMN protein_100g TYPE numeric(9,6),
 ALTER COLUMN carbs_100g TYPE numeric(9,6),
 ALTER COLUMN fat_100g TYPE numeric(9,6);
ALTER TABLE nutrition_diary_entry
 ADD COLUMN catalogue_id bigint REFERENCES food_catalogue(catalogue_id) ON DELETE RESTRICT,
 ADD COLUMN provenance jsonb NOT NULL DEFAULT '{}',
 ALTER COLUMN food_name TYPE varchar(300),
 ALTER COLUMN kcal_100g TYPE numeric(10,6),
 ALTER COLUMN protein_100g TYPE numeric(9,6),
 ALTER COLUMN carbs_100g TYPE numeric(9,6),
 ALTER COLUMN fat_100g TYPE numeric(9,6);
CREATE INDEX food_catalogue_active_idx ON food_catalogue(is_active);

-- Curated official USDA data; repeatable by permanent FDC identifier. No allergen claims.
